UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 45, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 46, 15, NULL::text),(3, 182, 36, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 222, 2936, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='14a1d325-7e38-5f8d-aa01-923bda126fc3' AND md5(a.contenido)='cbbd379fe162241eb9257be8ac23d73c' RETURNING a.id,md5(a.contenido) hash;